package com.m3mo.vault.domain.event

/**
 * Supplemental Events for Batch 7 Workers
 *
 * Only events NOT already defined in DomainEvent.kt.
 * All other events (DecayRunStarted/Completed, WeightChanged,
 * MemoryCreated/Updated/Deleted, SearchPerformed, etc.)
 * are already defined in DomainEvent.kt and reused directly.
 */

// ========== Review Events ==========

/**
 * Weekly review was generated by ReviewWorker
 */
data class ReviewGeneratedEvent(
    val weekStart: Long,
    val weekEnd: Long,
    val totalMemories: Int,
    val tasksCompleted: Int,
    val decayingCount: Int,
    val generatedAt: Long,
    override val timestamp: Long = System.currentTimeMillis()
) : DomainEvent

// ========== Cleanup Events ==========

/**
 * Cleanup worker completed
 */
data class CleanupCompletedEvent(
    val deletedCount: Int,
    val vacuumed: Boolean,
    val durationMs: Long,
    override val timestamp: Long = System.currentTimeMillis()
) : DomainEvent
